// Simplified HTTP call — removed nested fetch wrapper that caused stack overflow
const SB_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SB_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

const res = await this.helpers.httpRequest({
  method: 'GET',
  url: SB_URL + '/rest/v1/tasks?agent=eq.zara&status=eq.done&order=updated_at.desc&limit=5',
  headers: {
    'apikey': SB_KEY,
    'Authorization': 'Bearer ' + SB_KEY
  },
  json: true,
  returnFullResponse: false
});

const signals = Array.isArray(res) ? res : [];
if (signals.length === 0) {
  return [{ json: { signals: [], hasSignals: false } }];
}
return [{ json: { signals, hasSignals: true } }];

