const brief = $input.first().json.brief;
const posts = brief.trending_topics.slice(0, 3).map((topic, i) => {
  const hashtags = brief.keywords.slice(0, 3).map(k => '#' + k.replace(/\s+/g, '')).join(' ');
  return {
    agent: 'maya',
    title: 'Social Post: ' + topic.substring(0, 60),
    description: 'Draft social post about: ' + topic,
    status: 'pending',
    type: 'social_post',
    metadata: JSON.stringify({
      copy_suggestion: 'New insight from our research: ' + topic + '. ' + hashtags,
      platform: i === 0 ? 'twitter' : i === 1 ? 'linkedin' : 'instagram',
      source_brief: brief.title,
      keywords: brief.keywords.slice(0, 5),
      scheduled_for: new Date(Date.now() + (i + 1) * 3600000).toISOString()
    })
  };
});
if (posts.length > 0) {
  const resp = await fetch('https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/tasks', {
    method: 'POST',
    headers: {
      'apikey': '{{SUPABASE_SERVICE_ROLE_KEY}}',
      'Authorization': 'Bearer {{SUPABASE_SERVICE_ROLE_KEY}}',
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: JSON.stringify(posts)
  });
  const result = await resp.json();
  return [{ json: { posts_created: posts.length, result, brief_title: brief.title, newsletter_worthy: $input.first().json.newsletter_worthy } }];
}
return [{ json: { posts_created: 0, brief_title: brief.title, newsletter_worthy: $input.first().json.newsletter_worthy } }];

